/** Rotating Earth, camera zoom, then a clean FieldShift title screen. */
const copy={en:{title:'FieldShift',body:'Turn Earth observations and your own field records into clearer farming decisions. Explore local weather, water demand, soil conditions, resilient crop rotations and profit scenarios for the exact land you choose.',enter:'Enter FieldShift',replay:'Replay introduction',replayBody:'See the FieldShift introduction again.'},fr:{title:'FieldShift',body:'Transformez les observations de la Terre et vos propres relevés de terrain en décisions agricoles plus claires. Explorez la météo locale, les besoins en eau, l’état du sol, les rotations résilientes et les scénarios de bénéfices pour la terre choisie.',enter:'Entrer dans FieldShift',replay:'Revoir l’introduction',replayBody:'Revoir l’introduction de FieldShift.'},ar:{title:'فيلد شيفت',body:'حوّل رصد الأرض وسجلات حقلك إلى قرارات زراعية أوضح. استكشف الطقس المحلي واحتياجات المياه وحالة التربة وتناوب المحاصيل المرن وسيناريوهات الربح للأرض التي تختارها.',enter:'دخول فيلد شيفت',replay:'إعادة المقدمة',replayBody:'شاهد مقدمة فيلد شيفت مرة أخرى.'}};

function createEarth(canvas){
  const ctx=canvas.getContext('2d'),size=320,frame=ctx.createImageData(size,size),points=[];canvas.width=canvas.height=size;
  for(let y=0;y<size;y++)for(let x=0;x<size;x++){const nx=(x+.5-size/2)/(size/2),ny=(y+.5-size/2)/(size/2),radius=nx*nx+ny*ny;if(radius<=1){const nz=Math.sqrt(1-radius);points.push((y*size+x)*4,Math.atan2(nx,nz),Math.asin(-ny),Math.max(.22,.55+.52*(-nx*.45-ny*.38+nz*.82)));}}
  const texture=new Image();let pixels=null,animation=0,started=0;texture.onload=()=>{const source=document.createElement('canvas');source.width=texture.width;source.height=texture.height;const sourceCtx=source.getContext('2d',{willReadFrequently:true});sourceCtx.drawImage(texture,0,0);pixels=sourceCtx.getImageData(0,0,texture.width,texture.height).data;};texture.src='assets/earth-texture.jpg';
  const draw=now=>{if(!started)return;if(pixels){const turn=(now-started)/1200,data=frame.data,w=texture.width,h=texture.height;data.fill(0);for(let i=0;i<points.length;i+=4){const output=points[i],longitude=points[i+1]+turn,latitude=points[i+2],light=points[i+3],u=((longitude/(2*Math.PI)+.5)%1+1)%1,v=.5-latitude/Math.PI,source=((Math.min(h-1,Math.floor(v*h))*w+Math.floor(u*w))*4);data[output]=pixels[source]*light;data[output+1]=pixels[source+1]*light;data[output+2]=pixels[source+2]*light;data[output+3]=255;}ctx.putImageData(frame,0,0);}animation=requestAnimationFrame(draw);};
  return{start(){cancelAnimationFrame(animation);started=performance.now();animation=requestAnimationFrame(draw);},stop(){started=0;cancelAnimationFrame(animation);}};
}

export function initIntro({language='en'}={}){
  let current=copy[language]?language:'en',zoomTimer,revealTimer,hideTimer;
  const overlay=document.createElement('section');overlay.className='fieldshift-intro earth-intro';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','FieldShift introduction');
  overlay.innerHTML='<div class="earth-space" aria-hidden="true"><canvas class="earth-canvas"></canvas></div><div class="earth-intro-copy"><img class="earth-intro-logo" src="assets/logo-new.png" alt="FieldShift logo"><h1></h1><p></p><button type="button" class="earth-intro-enter"></button></div>';document.body.append(overlay);
  const earth=createEarth(overlay.querySelector('.earth-canvas')),enter=overlay.querySelector('.earth-intro-enter');
  const panel=document.querySelector('.settings-panel'),row=document.createElement('div');row.className='setting-item intro-replay-setting';row.innerHTML='<div><b></b><p></p></div><button type="button" class="button secondary small"></button>';panel.append(row);
  const apply=()=>{const words=copy[current];overlay.querySelector('h1').textContent=words.title;overlay.querySelector('p').textContent=words.body;enter.textContent=words.enter;row.querySelector('b').textContent=words.replay;row.querySelector('p').textContent=words.replayBody;row.querySelector('button').textContent=words.replay;};
  const clear=()=>{clearTimeout(zoomTimer);clearTimeout(revealTimer);clearTimeout(hideTimer);};
  const close=()=>{clear();earth.stop();sessionStorage.setItem('fieldshift.intro.skip-auto','1');overlay.classList.add('leaving');document.body.classList.remove('intro-open','intro-pending');hideTimer=setTimeout(()=>overlay.hidden=true,380);document.querySelector('.topbar-field')?.focus();window.dispatchEvent(new CustomEvent('fieldshift:intro:closed'));};
  const open=()=>{clear();earth.stop();overlay.hidden=false;overlay.classList.remove('leaving','zooming','revealed');document.body.classList.add('intro-open','intro-pending');enter.disabled=true;void overlay.offsetWidth;if(matchMedia('(prefers-reduced-motion: reduce)').matches){overlay.classList.add('revealed');enter.disabled=false;enter.focus();return;}earth.start();zoomTimer=setTimeout(()=>overlay.classList.add('zooming'),1000);revealTimer=setTimeout(()=>{earth.stop();overlay.classList.add('revealed');enter.disabled=false;enter.focus();},1950);};
  enter.onclick=close;row.querySelector('button').onclick=open;overlay.addEventListener('keydown',event=>{if(event.key==='Escape')close();});window.addEventListener('fieldshift:language',event=>{current=copy[event.detail]?event.detail:'en';apply();});apply();if(!sessionStorage.getItem('fieldshift.intro.skip-auto'))requestAnimationFrame(open);else {overlay.hidden=true;document.body.classList.remove('intro-pending');}return{open};
}
